"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
}

DAY_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3,
    'THU': 4, 'FRI': 5, 'SAT': 6
}


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    if count == 0:
        return []

    fields = expr.split()
    if len(fields) != 5:
        raise CronError(f"Expression must have exactly 5 fields, got {len(fields)}")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minute_values, _ = parse_field(minute_field, 0, 59, None)
    hour_values, _ = parse_field(hour_field, 0, 23, None)
    dom_values, dom_restricted = parse_field(dom_field, 1, 31, None)
    month_values, _ = parse_field(month_field, 1, 12, 'month')
    dow_values, dow_restricted = parse_field(dow_field, 0, 7, 'dow')

    if dow_values is not None:
        dow_values = {0 if v == 7 else v for v in dow_values}

    results = []
    current = start + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    end_search = start + timedelta(days=365*5)

    while current <= end_search and len(results) < count:
        if matches(current, minute_values, hour_values, dom_values, month_values, dow_values, dom_restricted, dow_restricted):
            results.append(current)
        current += timedelta(minutes=1)

    if len(results) < count:
        raise CronError(f"No firing exists within 5 years of {start}")

    return results


def parse_field(field: str, min_val: int, max_val: int, field_type: str | None) -> tuple[set[int] | None, bool]:
    """Parse a cron field. Returns (values, is_restricted)."""
    if field == '*':
        return None, False

    values = set()
    for term in field.split(','):
        values.update(parse_term(term, min_val, max_val, field_type))

    return values, True


def parse_term(term: str, min_val: int, max_val: int, field_type: str | None) -> set[int]:
    """Parse a single term in a cron field."""
    if '/' in term:
        range_part, step_str = term.rsplit('/', 1)
        try:
            step = int(step_str)
        except ValueError:
            raise CronError(f"Invalid step: {step_str}")

        if step < 1:
            raise CronError(f"Step must be >= 1, got {step}")

        if range_part == '*':
            return set(range(min_val, max_val + 1, step))
        elif '-' in range_part:
            a, b = parse_range(range_part, field_type)
            if a < min_val or b > max_val:
                raise CronError("Range out of bounds")
            if a > b:
                raise CronError(f"Invalid range: {a} > {b}")
            return set(range(a, b + 1, step))
        else:
            n = normalize_value(range_part, field_type)
            if n < min_val or n > max_val:
                raise CronError("Value out of bounds")
            return set(range(n, max_val + 1, step))
    elif '-' in term:
        a, b = parse_range(term, field_type)
        if a < min_val or b > max_val:
            raise CronError("Range out of bounds")
        if a > b:
            raise CronError(f"Invalid range: {a} > {b}")
        return set(range(a, b + 1))
    else:
        n = normalize_value(term, field_type)
        if n < min_val or n > max_val:
            raise CronError("Value out of bounds")
        return {n}


def parse_range(range_str: str, field_type: str | None) -> tuple[int, int]:
    """Parse a range like '1-5' or 'JAN-MAR'."""
    parts = range_str.split('-', 1)
    if len(parts) != 2:
        raise CronError(f"Invalid range: {range_str}")
    a = normalize_value(parts[0], field_type)
    b = normalize_value(parts[1], field_type)
    return a, b


def normalize_value(val_str: str, field_type: str | None) -> int:
    """Convert a value string (which may be a name) to an integer."""
    val_str = val_str.upper()

    if field_type == 'month' and val_str in MONTH_NAMES:
        return MONTH_NAMES[val_str]
    elif field_type == 'dow' and val_str in DAY_NAMES:
        return DAY_NAMES[val_str]

    try:
        return int(val_str)
    except ValueError:
        raise CronError(f"Invalid value: {val_str}")


def matches(
    dt: datetime,
    minute_values: set[int] | None,
    hour_values: set[int] | None,
    dom_values: set[int] | None,
    month_values: set[int] | None,
    dow_values: set[int] | None,
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    """Check if a datetime matches the cron expression."""
    if minute_values is not None and dt.minute not in minute_values:
        return False

    if hour_values is not None and dt.hour not in hour_values:
        return False

    if month_values is not None and dt.month not in month_values:
        return False

    if dom_restricted and dow_restricted:
        dom_match = dt.day in dom_values
        dow_match = cron_dow_matches(dt, dow_values)
        return dom_match or dow_match
    elif dom_restricted:
        return dt.day in dom_values
    elif dow_restricted:
        return cron_dow_matches(dt, dow_values)
    else:
        return True


def cron_dow_matches(dt: datetime, dow_values: set[int]) -> bool:
    """Check if a datetime's day-of-week matches the given cron dow values."""
    python_dow = dt.weekday()
    cron_dow = (python_dow + 1) % 7
    return cron_dow in dow_values
